def is_type_b(N):
    V = [False] * (N + 1)
    for n in range(N - 1, 0, -1):
        # Check if n+1 can lead to a win
        can_win = False
        # Option 1: n+1
        m1 = n + 1
        if m1 == N:
            can_win = True
        elif m1 < N and not V[m1]:
            can_win = True

        # Option 2: 2n
        if not can_win:
            m2 = 2 * n
            if m2 == N:
                can_win = True
            elif m2 < N and not V[m2]:
                can_win = True

        V[n] = can_win
    return V[1]

type_b_numbers = []
for n in range(1, 1000):
    if is_type_b(n):
        type_b_numbers.append(n)

print(type_b_numbers)
